"""Demo C: Greedy list coloring along a degeneracy ordering.

A d-degenerate graph is (d+1)-choosable. K_{2,4} is 2-degenerate, so any
assignment of 3-element lists is satisfiable. This demo colors the vertices in a
degeneracy order, always picking the least admissible color not used by an
already-colored neighbor, and verifies the output is a proper list coloring.
"""
from typing import Dict, List, Set, Tuple

Vertex = Tuple[str, int]

def greedy(order: List[Vertex],
           neighbors: Dict[Vertex, List[Vertex]],
           lists: Dict[Vertex, Set[int]]) -> Dict[Vertex, int]:
    color: Dict[Vertex, int] = {}
    for v in order:
        used = {color[u] for u in neighbors[v] if u in color}
        choice = min(c for c in sorted(lists[v]) if c not in used)
        color[v] = choice
    return color

def main() -> None:
    left = [("A", 0), ("A", 1)]
    right = [("B", j) for j in range(4)]
    neighbors: Dict[Vertex, List[Vertex]] = {}
    for a in left:
        neighbors[a] = list(right)
    for b in right:
        neighbors[b] = list(left)
    lists: Dict[Vertex, Set[int]] = {
        ("A", 0): {0, 1, 2}, ("A", 1): {0, 1, 2},
        ("B", 0): {0, 1, 3}, ("B", 1): {0, 2, 3},
        ("B", 2): {1, 2, 3}, ("B", 3): {0, 1, 2},
    }
    order = right + left  # large side first: each large vertex has 0 back-neighbors
    c = greedy(order, neighbors, lists)
    edges = [(a, b) for a in left for b in right]
    assert all(c[u] != c[v] for u, v in edges)
    assert all(c[v] in lists[v] for v in c)
    print("Greedy proper list coloring (all lists size 3):")
    for v in left + right:
        print(f"  {v}: {c[v]}")

if __name__ == "__main__":
    main()

