function DECIDE(vertices, edges, L):
  build adjacency lists adj from edges
  color := empty map
  function EXTEND(i):
    if i = |vertices|: return true
    v := vertices[i]
    for c in sorted(L[v]):
      if c != color[u] for every neighbor u of v already colored:
        color[v] := c
        if EXTEND(i+1): return true
        unset color[v]
    return false
  if EXTEND(0): return color else return NONE

