function BLOCKING_ASSIGNMENT(k):
  for i in 0..k-1: S[i] := { i*k, ..., i*k + k - 1 }   # disjoint k-lists
  systems := cartesian_product(S[0], ..., S[k-1])       # k^k systems
  for i in 0..k-1: L[A_i] := S[i]
  for j, s in enumerate(systems): L[B_j] := set(s)
  edges := { (A_i, B_j) for all i, j }
  return L, edges

